#[path = "solution.rs"]
mod solution;

use solution::build_factories;

#[test]
fn parses_trims_and_preserves_catalog_and_capability_order() {
    let records = [
        " alpha | First Extension | 1.0 | read, write ,admin ",
        "beta|First Extension|2|",
    ];
    let mut factories = build_factories(&records).unwrap();
    assert_eq!(factories.len(), 2);

    let first = factories[0].descriptor();
    assert_eq!(first.id, "alpha");
    assert_eq!(first.title, "First Extension");
    assert_eq!(first.revision, "1.0");
    assert_eq!(first.capabilities, vec!["read", "write", "admin"]);

    let second = factories[1].descriptor();
    assert_eq!(second.id, "beta");
    assert_eq!(second.title, "First Extension");
    assert_eq!(second.revision, "2");
    assert!(second.capabilities.is_empty());

    let instance = factories[0].create().unwrap();
    assert_eq!(instance.serial, 1);
    assert_eq!(instance.descriptor.id, "alpha");
    assert_eq!(instance.descriptor.capabilities, vec!["read", "write", "admin"]);
}

#[test]
fn serials_start_at_one_and_are_independent_per_factory() {
    let records = ["a|A|r|x", "b|B|r|y"];
    let mut factories = build_factories(&records).unwrap();
    assert_eq!(factories[0].create().unwrap().serial, 1);
    assert_eq!(factories[0].create().unwrap().serial, 2);
    assert_eq!(factories[1].create().unwrap().serial, 1);
    assert_eq!(factories[0].descriptor().id, "a");
}

#[test]
fn empty_catalog_is_valid() {
    let factories = build_factories(&[]).unwrap();
    assert!(factories.is_empty());
}

#[test]
fn rejects_bad_field_counts_and_empty_required_fields() {
    for records in [
        vec!["a|title|rev"],
        vec!["a|title|rev|cap|extra"],
        vec![" |title|rev|cap"],
        vec!["a|  |rev|cap"],
        vec!["a|title|  |cap"],
    ] {
        assert!(build_factories(&records).is_err());
    }
}

#[test]
fn rejects_empty_or_duplicate_capabilities_after_trimming() {
    assert!(build_factories(&["a|A|1|read,,write"]).is_err());
    assert!(build_factories(&["a|A|1|read,   ,write"]).is_err());
    assert!(build_factories(&["a|A|1|read, write,read "]).is_err());
    assert!(build_factories(&["a|A|1|,read"]).is_err());
    assert!(build_factories(&["a|A|1|read,"]).is_err());
}

#[test]
fn duplicate_ids_are_rejected_after_field_trimming() {
    let records = ["same|One|1|", " same |Two|2|cap"];
    assert!(build_factories(&records).is_err());
}

#[test]
fn building_and_creating_do_not_change_record_text() {
    let owned = String::from(" id | title | rev | one,two ");
    let original = owned.clone();
    {
        let records = [owned.as_str()];
        let mut factories = build_factories(&records).unwrap();
        let _ = factories[0].create().unwrap();
    }
    assert_eq!(owned, original);
}

